import{_ as o,a0 as p,w as u,s as r,I as t,x as s,a1 as e,A as n,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"3 個 Linux 上的 SSH 圖形界面工具 | LCTT x X-CMD","titleTemplate":false,"description":"3 個 Linux 上的 SSH 圖形界面工具 | LCTT (201902) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"3 個 Linux 上的 SSH 圖形界面工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"3 個 Linux 上的 SSH 圖形界面工具 | LCTT (201902) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201902/20181123 Three SSH GUI Tools for Linux","title":"3 個 Linux 上的 SSH 圖形界面工具","tag":"201902","desc":""},"relativePath":"201902/20181123 Three SSH GUI Tools for Linux.md","filePath":"[post].md"}'),d={name:"201902/20181123 Three SSH GUI Tools for Linux.md"};function S(m,i,T,g,f,x){const l=p("Link");return u(),r("div",null,[i[27]||(i[27]=t("h1",{id:"_3-個-linux-上的-ssh-圖形界面工具",tabindex:"-1"},[s("3 個 Linux 上的 SSH 圖形界面工具 "),t("a",{class:"header-anchor",href:"#_3-個-linux-上的-ssh-圖形界面工具","aria-label":"Permalink to “3 個 Linux 上的 SSH 圖形界面工具”"},"​")],-1)),i[28]||(i[28]=t("blockquote",null,[t("p",null,"瞭解一下這三個用於 Linux 上的 SSH 圖形界面工具。")],-1)),i[29]||(i[29]=t("p",null,[t("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/ssh.jpg?itok=3UcXhJt7",alt:""})],-1)),i[30]||(i[30]=t("p",null,"在你擔任 Linux 管理員的職業生涯中，你會使用 Secure Shell（SSH）遠程連接到 Linux 服務器或桌面。可能你曾經在某些情況下，會同時 SSH 連接到多個 Linux 服務器。實際上，SSH 可能是 Linux 工具箱中最常用的工具之一。因此，你應該儘可能提高體驗效率。對於許多管理員來説，沒有什麼比命令列更有效了。但是，有些用户更喜歡使用 GUI 工具，尤其是在從台式機連接到遠程並在服務器上工作時。",-1)),i[31]||(i[31]=t("p",null,"如果你碰巧喜歡好的圖形界面工具，你肯定很樂於瞭解一些 Linux 上優秀的 SSH 圖形界面工具。讓我們來看看這三個工具，看看它們中的一個（或多個）是否完全符合你的需求。",-1)),t("p",null,[i[1]||(i[1]=s("我將在 ",-1)),e(l,{href:"https://elementary.io/"},{default:n(()=>[...i[0]||(i[0]=[s("Elementary OS",-1)])]),_:1}),i[2]||(i[2]=s(" 上演示這些工具，但它們都可用於大多數主要發行版。",-1))]),i[32]||(i[32]=t("h3",{id:"putty",tabindex:"-1"},[s("PuTTY "),t("a",{class:"header-anchor",href:"#putty","aria-label":"Permalink to “PuTTY”"},"​")],-1)),t("p",null,[i[4]||(i[4]=s("已經有一些經驗的人都知道 ",-1)),e(l,{href:"https://www.chiark.greenend.org.uk/~sgtatham/putty/latest.html"},{default:n(()=>[...i[3]||(i[3]=[s("PuTTY",-1)])]),_:1}),i[5]||(i[5]=s("。實際上，從 Windows 環境通過 SSH 連接到 Linux 服務器時，PuTTY 是事實上的標準工具。但 PuTTY 不僅適用於 Windows。事實上，通過標準軟件庫，PuTTY 也可以安裝在 Linux 上。 PuTTY 的功能列表包括：",-1))]),i[33]||(i[33]=a('<ul><li>保存會話。</li><li>通過 IP 或主機名連接。</li><li>使用替代的 SSH 端口。</li><li>定義連接類型。</li><li>日誌。</li><li>設置鍵盤、響鈴、外觀、連接等等。</li><li>配置本地和遠程隧道。</li><li>支持代理。</li><li>支持 X11 隧道。</li></ul><p>PuTTY 圖形工具主要是一種保存 SSH 會話的方法，因此可以更輕鬆地管理所有需要不斷遠程進出的各種 Linux 服務器和桌面。一旦連接成功，PuTTY 就會建立一個到 Linux 服務器的連接窗口，你將可以在其中工作。此時，你可能會有疑問，為什麼不在終端窗口工作呢？對於一些人來説，保存會話的便利確實使 PuTTY 值得使用。</p><p>在 Linux 上安裝 PuTTY 很簡單。例如，你可以在基於 Debian 的發行版上運行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install -y putty</span></span></code></pre></div><p>安裝後，你可以從桌面菜單運行 PuTTY 圖形工具或運行命令 <code>putty</code>。在 PuTTY “Configuration” 窗口（圖 1）中，在 “HostName (or IP address) ” 部分鍵入主機名或 IP 地址，配置 “Port”（如果不是默認值 22），從 “Connection type”中選擇 SSH，然後單擊“Open”。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/ssh_guis_1.jpg?itok=DiNTz_wO" alt="PuTTY Connection" title="PuTTY Connection"></p><p><em>圖 1：PuTTY 連接配置窗口</em></p><p>建立連接後，系統將提示你輸入遠程服務器上的用户憑據（圖2）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/ssh_guis_2.jpg?itok=4ORsJlz3" alt="log in" title="log in"></p><p><em>圖 2：使用 PuTTY 登錄到遠程服務器</em></p><p>要保存會話（以便你不必始終鍵入遠程服務器信息），請填寫主機名（或 IP 地址）、配置端口和連接類型，然後（在單擊 “Open” 之前），在 “Saved Sessions” 部分的頂部文本區域中鍵入名稱，然後單擊 “Save”。這將保存會話的配置。若要連接到已保存的會話，請從 “Saved Sessions” 窗口中選擇它，單擊 “Load”，然後單擊 “Open”。系統會提示你輸入遠程服務器上的遠程憑據。</p><h3 id="easyssh" tabindex="-1">EasySSH <a class="header-anchor" href="#easyssh" aria-label="Permalink to “EasySSH”">​</a></h3>',12)),t("p",null,[i[7]||(i[7]=s("雖然 ",-1)),e(l,{href:"https://github.com/muriloventuroso/easyssh"},{default:n(()=>[...i[6]||(i[6]=[s("EasySSH",-1)])]),_:1}),i[8]||(i[8]=s(" 沒有提供 PuTTY 中的那麼多的配置選項，但它（顧名思義）非常容易使用。 EasySSH 的最佳功能之一是它提供了一個標籤式界面，因此你可以打開多個 SSH 連接並在它們之間快速切換。EasySSH 的其他功能包括：",-1))]),i[34]||(i[34]=a(`<ul><li>分組（出於更好的體驗效率，可以對標籤進行分組）。</li><li>保存用户名、密碼。</li><li>外觀選項。</li><li>支持本地和遠程隧道。</li></ul><p>在 Linux 桌面上安裝 EasySSH 很簡單，因為可以通過 Flatpak 安裝應用程序（這意味着你必須在系統上安裝 Flatpak）。安裝 Flatpak 後，使用以下命令添加 EasySSH：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo flatpak remote-add --if-not-exists flathub https://flathub.org/repo/flathub.flatpakrepo</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sudo flatpak install flathub com.github.muriloventuroso.easyssh</span></span></code></pre></div><p>用如下命令運行 EasySSH：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak run com.github.muriloventuroso.easyssh</span></span></code></pre></div><p>將會打開 EasySSH 應用程序，你可以單擊左上角的 “+” 按鈕。 在結果窗口（圖 3）中，根據需要配置 SSH 連接。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/ssh_guis_3.jpg?itok=bHC2zlda" alt="Adding a connection" title="Adding a connection"></p><p><em>圖 3：在 EasySSH 中添加連接很簡單</em></p><p>添加連接後，它將顯示在主窗口的左側導航中（圖 4）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/ssh_guis_4.jpg?itok=hhJzhRIg" alt="EasySSH" title="EasySSH"></p><p><em>圖 4：EasySSH 主窗口</em></p><p>要在 EasySSH 連接到遠程服務器，請從左側導航欄中選擇它，然後單擊 “Connect” 按鈕（圖 5）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/ssh_guis_5.jpg?itok=piFEFYTQ" alt="Connecting" title="Connecting"></p><p><em>圖 5：用 EasySSH 連接到遠程服務器</em></p><p>對於 EasySSH 的一個警告是你必須將用户名和密碼保存在連接配置中（否則連接將失敗）。這意味着任何有權訪問運行 EasySSH 的桌面的人都可以在不知道密碼的情況下遠程訪問你的服務器。因此，你必須始終記住在你離開時鎖定桌面屏幕（並確保使用強密碼）。否則服務器容易受到意外登錄的影響。</p><h3 id="terminator" tabindex="-1">Terminator <a class="header-anchor" href="#terminator" aria-label="Permalink to “Terminator”">​</a></h3><p>（LCTT 譯註：這個選擇不符合本文主題，本節刪節）</p><h3 id="termius" tabindex="-1">termius <a class="header-anchor" href="#termius" aria-label="Permalink to “termius”">​</a></h3><p>（LCTT 譯註：本節是根據網友推薦補充的）</p>`,19)),t("p",null,[i[10]||(i[10]=s("termius 是一個商業版的 SSH、Telnet 和 Mosh 客户端，不是開源軟件。支持包括 ",-1)),e(l,{href:"https://www.termius.com/linux"},{default:n(()=>[...i[9]||(i[9]=[s("Linux",-1)])]),_:1}),i[11]||(i[11]=s("、Windows、Mac、iOS 和安卓在內的各種操作系統。對於單一設備是免費的，支持多設備的白金賬號需要按月付費。",-1))]),i[35]||(i[35]=t("h3",{id:"很少-但值得-的選擇",tabindex:"-1"},[s("很少（但值得）的選擇 "),t("a",{class:"header-anchor",href:"#很少-但值得-的選擇","aria-label":"Permalink to “很少（但值得）的選擇”"},"​")],-1)),i[36]||(i[36]=t("p",null,"Linux 上沒有很多可用的 SSH 圖形界面工具。為什麼？因為大多數管理員更喜歡簡單地打開終端窗口並使用標準命令列工具來遠程訪問其服務器。但是，如果你需要圖形界面工具，則有兩個可靠選項，可以更輕鬆地登錄多台計算機。雖然對於那些尋找 SSH 圖形界面工具的人來説只有不多的幾個選擇，但那些可用的工具當然值得你花時間。嘗試其中一個，親眼看看。",-1)),i[37]||(i[37]=t("hr",null,null,-1)),t("p",null,[i[13]||(i[13]=s("via: ",-1)),e(l,{href:"https://www.linux.com/blog/learn/intro-to-linux/2018/11/three-ssh-guis-linux"},{default:n(()=>[...i[12]||(i[12]=[s("https://www.linux.com/blog/learn/intro-to-linux/2018/11/three-ssh-guis-linux",-1)])]),_:1})]),t("p",null,[i[18]||(i[18]=s("作者：",-1)),e(l,{href:"https://www.linux.com/users/jlwallen"},{default:n(()=>[...i[14]||(i[14]=[s("Jack Wallen",-1)])]),_:1}),i[19]||(i[19]=s(" 選題：",-1)),e(l,{href:"https://github.com/lujun9972"},{default:n(()=>[...i[15]||(i[15]=[s("lujun9972",-1)])]),_:1}),i[20]||(i[20]=s(" 譯者：",-1)),e(l,{href:"https://github.com/wxy"},{default:n(()=>[...i[16]||(i[16]=[s("wxy",-1)])]),_:1}),i[21]||(i[21]=s(" 校對：",-1)),e(l,{href:"https://github.com/wxy"},{default:n(()=>[...i[17]||(i[17]=[s("wxy",-1)])]),_:1})]),t("p",null,[i[24]||(i[24]=s("本文由 ",-1)),e(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...i[22]||(i[22]=[s("LCTT",-1)])]),_:1}),i[25]||(i[25]=s(" 原創編譯，",-1)),e(l,{href:"https://linux.cn/"},{default:n(()=>[...i[23]||(i[23]=[s("Linux中國",-1)])]),_:1}),i[26]||(i[26]=s(" 榮譽推出",-1))])])}const y=o(d,[["render",S]]);export{k as __pageData,y as default};
